// TestABIReuse calls twice through the funnel; both results must be correct. This
// catches a recycle-aliasing regression like the one #457 fixed — where a stale or
// aliased *syscallArgs would corrupt a subsequent call.
func TestABIReuse(t *testing.T) {
	fn := buildSym(t, srcSum15, "sum15")
	for i := 0; i < 2; i++ {
		var args [ffi.MaxArgs]uintptr
		for k := 0; k < 15; k++ {
			args[k] = uintptr(k + 1) // 1..15, sum = 120
		}
		r1, _, _ := ffi.Call(fn, 15, &args, 0)
		if int64(r1) != 120 {
			t.Fatalf("iter %d: sum15 = %d, want 120 (pool recycle or layout drift)", i, int64(r1))
		}
	}
}

// TestABIAllocBudget asserts that the dispatch pool eliminates steady-state
// allocation after warmup.
func TestABIAllocBudget(t *testing.T) {
	fn := buildSym(t, srcSum15, "sum15")
	var args [ffi.MaxArgs]uintptr
	args[0] = 1
	allocs := testing.AllocsPerRun(1000, func() {
		ffi.Call(fn, 15, &args, 0)
	})
	if allocs != 0 {
		t.Fatalf("ffi.Call = %v allocs/op, want 0", allocs)
	}
}
